(()=>{
const g=__rhf.game, W=g.world, C=g.colliders, wl=g.wildlife;
g.state.settings.autoQuality=false; g.setQuality('high'); g.dpr=1; g.renderer.setPixelRatio(1); g.resize();
g.bears.directorT=1e9;
const we=g.env.weather; we.cloud=we.cloudTarget=0.25; we.rain=we.rainTarget=0; we.timer=1e9;
g.env.timeScale=0; g.hud.firstShown=-1000; g.hud.hint('',0); g.hud.show(false); __rhf.god(true);
wl.threatPos=()=>({x:1e7,z:1e7,loud:0}); for(const a of wl.animals) a.cfg.flee=0;
let seed=24680; window.__rnd=()=>((seed=(seed*16807)%2147483647)/2147483647);
window.__wait=(ms)=>new Promise(r=>setTimeout(r,ms));
window.__hands=(on)=>{ g.player.tool=on?'rod':'none'; g.viewmodel.setTool(on?'rod':'none'); };
// the reflections made again for the place and the hour: the water's (the
// game renews one of its five faces a frame, and at a software renderer's
// frame rate faces from the last place would still be in the picture) and
// the sky's map that lights and shines on everything (renewed at most every
// 5 s, so a jump from sunset to night could keep the sunset in it)
window.__probe=()=>{ if(__rhf.session&&__rhf.session.updateEnvMap) __rhf.session.updateEnvMap(); const w=g.water; if(!w.probe) return; g.camera.updateMatrixWorld(); w.viewLevel=w.levelAhead(g.camera); const pos=g.camera.position.clone(); if(w.viewLevel!==null&&w.viewLevel<pos.y) pos.y=w.viewLevel+0.3; w.probe.update(g.renderer,g.scene,pos,5); };
// a place, a time of day, a pitch and a turn from the place's own facing
window.__go=async(id,time,pitch,yawOff,spot)=>{ __hands(false); if(spot){ g.player.place(spot.x,spot.z,yawOff||0); } else { const p=W.place(id); g.player.place(p.x,p.z,(p.face??0)+(yawOff||0)); } g.player.pitch=pitch; g.env.setTime(time); await __wait(3000); __probe(); return id+' at '+time; };
// from a place, face a far point
window.__face=async(id,tx,tz,time,pitch)=>{ __hands(false); const p=W.place(id); g.env.setTime(time); g.player.place(p.x,p.z,Math.atan2(-(tx-p.x),-(tz-p.z))); g.player.pitch=pitch; await __wait(4000); __probe(); return id+' facing '+Math.round(Math.hypot(tx-p.x,tz-p.z))+' m'; };
// stand dist metres from a point, in the direction ang from its front, and look at it
window.__look=async(cx,cy,cz,front,ang,dist,time)=>{ __hands(false); const P=g.player; g.env.setTime(time); const x=cx+Math.sin(front+ang)*dist, z=cz+Math.cos(front+ang)*dist; P.place(x,z,0); const ey=P.pos.y+1.66; P.yaw=Math.atan2(-(cx-x),-(cz-z)); P.pitch=Math.atan2(cy-ey,Math.hypot(cx-x,cz-z)); await __wait(3000); __probe(); return 'looking from '+x.toFixed(0)+','+z.toFixed(0); };
// Bear Falls from the bank
window.__falls=async(off,side,time)=>{ __hands(false); const p=W.river.sample(W.fallsS+off); const t=W.river.sample(W.fallsS); const w=W.riverWidth(W.fallsS+off)+side; const x=p.x-p.tz*w, z=p.z+p.tx*w; g.env.setTime(time); g.player.place(x,z,0); const dx=t.x-x, dz=t.z-z; g.player.yaw=Math.atan2(-dx,-dz); g.player.pitch=Math.atan2(W.riverLevel(W.fallsS)-5-(g.player.pos.y+1.7),Math.hypot(dx,dz)); g.bears.bears.forEach(b=>{if(b.mode!=='fish'){b.state='gone'; b.t=9999;}}); await __wait(6000); __probe(); return 'falls from '+Math.round(Math.hypot(dx,dz))+' m'; };
// the tree of a kind nearest a point, from dist metres
const T=g.scatter.types;
window.__tree=async(type,near,dist,time)=>{ __hands(false); g.env.setTime(time); const t=T[type]; let bi=-1, bd=1e18; for(let i=0;i<t.count;i++){ const d=(t.x[i]-near.x)**2+(t.z[i]-near.z)**2; if(d<bd){bd=d; bi=i;} } if(bi<0) return type+': none'; const tx=t.x[bi], tz=t.z[bi]; let best=null; for(let k=0;k<48;k++){ const a=k/48*6.283; const x=tx+Math.cos(a)*dist, z=tz+Math.sin(a)*dist; if(!W.inBounds(x,z,10)) continue; const w=W.waterAt(x,z); if(w&&w.depth>0.1) continue; if(C.circlesNear(x,z,1.5).some(c=>Math.hypot(c.x-x,c.z-z)<c.r+0.5)) continue; const h=W.heightAt(x,z); let clear=0; for(let i=1;i<10;i++){ const q=i/10; clear+=W.heightAt(x+(tx-x)*q,z+(tz-z)*q)>h+1.7+((t.y[bi]+6)-(h+1.7))*q?1:0; } const sc=clear*10+Math.abs(h-t.y[bi])*0.2; if(!best||sc<best.sc) best={x,z,h,sc}; } if(!best) return type+': no spot'; g.player.place(best.x,best.z,Math.atan2(-(tx-best.x),-(tz-best.z))); g.player.pitch=Math.atan2(t.y[bi]+6-(best.h+1.7),dist)*0.8; await __wait(3000); __probe(); return type+' from '+dist+' m'; };
// an animal of a species posed near a point, the camera dist metres away with the sun behind it
// (bears live in the bear system, the rest among the wildlife; the falls
// view sends the roaming bears away, so a bear is brought back for its view)
const sun=()=>{const s=g.env.sunDir; const l=Math.hypot(s.x,s.z)||1; return {x:s.x/l,z:s.z/l};};
window.__animal=async(sp,cx,cz,R,dist,h,time)=>{ __hands(false); g.env.setTime(time); const all=(sp==='blackbear'||sp==='grizzly'?g.bears.bears.filter(a=>a.species===sp&&!a.dead):wl.animals.filter(a=>a.species===sp&&!a.dead&&a.state!=='gone')); if(!all.length) return sp+': none'; const hab=wl.habitats[sp]; let p=null; for(let t=0;t<4000&&!p;t++){ const a=__rnd()*6.2832, r=Math.sqrt(__rnd())*R; const x=cx+Math.cos(a)*r, z=cz+Math.sin(a)*r; if(!W.inBounds(x,z,20)||!hab(x,z)||W.waterAt(x,z)||W.slopeAt(x,z)>0.3||C.circlesNear(x,z,2.5).length) continue; p={x,z}; } if(!p) return sp+': no spot'; const L=sun(); const ty=W.heightAt(p.x,p.z)+h; let cam=null; for(let k=0;k<60;k++){ const a=k/60*6.2832; const x=p.x+Math.cos(a)*dist, z=p.z+Math.sin(a)*dist; if(!W.inBounds(x,z,10)||W.waterAt(x,z)||C.circlesNear(x,z,1.6).length) continue; const eye=W.heightAt(x,z)+1.7; let clear=true; for(let i=1;i<20;i++){ const q=i/20; if(W.heightAt(x+(p.x-x)*q,z+(p.z-z)*q)>eye+(ty-eye)*q-0.3*(1-q)){clear=false;break;} } if(!clear) continue; let trees=0; for(let i=1;i<12;i++){ const q=i/12; trees+=C.circlesNear(x+(p.x-x)*q,z+(p.z-z)*q,1.3).length; } const ux=(x-p.x)/dist, uz=(z-p.z)/dist; const sc=trees*20+Math.abs(ux*L.x+uz*L.z-0.75)*6; if(!cam||sc<cam.sc) cam={x,z,sc}; } if(!cam) return sp+': no camera spot'; const a0=all[0]; const yaw=Math.atan2(p.x-cam.x,p.z-cam.z)+(Math.PI/2+0.5); Object.assign(a0,{x:p.x,z:p.z,yaw,state:a0.isBear?'roam':'idle',visible:true,t:9999,speed:0,targetSpeed:0,amp:0,head:0,headT:0,homeX:p.x,homeZ:p.z}); for(const b of all.slice(1)) if(Math.hypot(b.x-cam.x,b.z-cam.z)<40) Object.assign(b,{x:b.x+90,z:b.z+90,homeX:b.x+90,homeZ:b.z+90}); g.player.place(cam.x,cam.z,Math.atan2(-(p.x-cam.x),-(p.z-cam.z))-0.2); g.player.pitch=Math.atan2(ty-(W.heightAt(cam.x,cam.z)+1.7),dist); await __wait(3500); __probe(); return sp+' at '+p.x.toFixed(0)+','+p.z.toFixed(0); };
// the hot rod from a three-quarter view
window.__car=async(time)=>{ __hands(false); g.env.setTime(time); const c=g.hotrod; const P=c.pos; const a=c.yaw+2.35, d=6.5; const x=P.x+Math.sin(a)*d, z=P.z+Math.cos(a)*d; g.player.place(x,z,0); g.player.yaw=Math.atan2(-(P.x-x),-(P.z-z)); g.player.pitch=Math.atan2(P.y+0.7-(g.player.pos.y+1.7),d); await __wait(3000); __probe(); return 'hot rod at '+P.x.toFixed(0)+','+P.z.toFixed(0); };
// first person with the rod, at a fishing place
window.__rod=async(id,time,pitch)=>{ const p=W.place(id); g.player.place(p.x,p.z,p.face??0); g.player.pitch=pitch; g.env.setTime(time); __hands(true); await __wait(3500); __probe(); return 'rod at '+id; };
// cloud shadows drift with the clock, and the cloud pattern is one of the
// things compared: none in these views, so a passing cloud does not decide
// how a pair looks
let cu=null; g.scene.traverse(o=>{ if(cu||!o.isMesh) return; const m=Array.isArray(o.material)?o.material[0]:o.material; const u=m&&g.renderer.properties.get(m).uniforms; if(u&&u.uFxClouds) cu=u.uFxClouds; });
if(cu) Object.defineProperty(cu.value,'w',{get:()=>0,set:()=>{}});
// a spot deep in the forest near the landing
const P0=W.place('landing'); let forest=null; for(let r=40;r<600&&!forest;r+=20){ for(let a=0;a<24;a++){ const x=P0.x+Math.cos(a/24*6.283)*r, z=P0.z+Math.sin(a/24*6.283)*r; if(!W.inBounds(x,z)) continue; const k=W.cellIndex(x,z); if(W.forest[k]>210 && !W.waterAt(x,z)){ forest={x,z}; break; } } }
window.__forest=forest;
return 'ok, forest '+(forest?Math.round(forest.x)+','+Math.round(forest.z):'none')+(cu?', no cloud shadows':', cloud shadows NOT found');
})()
